window.GLOSSAR = [{"id": 1, "tag": 1, "de_begriff": "Duales System", "de": "Ausbildung an zwei Lernorten, im Betrieb und in der Berufsschule.", "fa_begriff": "نظام دوگانه (Duales System)", "fa": "آموزش حرفه‌ای در دو محل یادگیری انجام می‌شود، در شرکت و در مدرسه‌ی حرفه‌ای (Berufsschule).", "ru_begriff": "дуальная система (duales System)", "ru": "Обучение в двух местах, на предприятии и в профессиональной школе (Berufsschule)."}, {"id": 2, "tag": 1, "de_begriff": "Überbetriebliche Ausbildung", "de": "Teile der Ausbildung in einer geeigneten Einrichtung außerhalb des Betriebs, zum Beispiel in einer Lehrwerkstatt.", "fa_begriff": "آموزش خارج از شرکت (Überbetriebliche Ausbildung)", "fa": "بخش‌هایی از آموزش در یک مرکز مناسب بیرون از شرکت انجام می‌شود، برای مثال در کارگاه آموزشی.", "ru_begriff": "обучение вне предприятия (überbetriebliche Ausbildung)", "ru": "Части обучения проходят в подходящем учреждении вне предприятия, например в учебной мастерской (Lehrwerkstatt)."}, {"id": 3, "tag": 1, "de_begriff": "BBiG", "de": "Berufsbildungsgesetz des Bundes. Es regelt Ausbildung, Fortbildung und Umschulung.", "fa_begriff": "BBiG، قانون آموزش حرفه‌ای (Berufsbildungsgesetz)", "fa": "قانون فدرال آموزش حرفه‌ای. این قانون آموزش حرفه‌ای، دوره‌های ارتقای حرفه‌ای و بازآموزی را تنظیم می‌کند.", "ru_begriff": "BBiG, Закон о профессиональном образовании (Berufsbildungsgesetz)", "ru": "Федеральный закон о профессиональном образовании. Он регулирует профессиональное обучение, повышение квалификации и переобучение."}, {"id": 4, "tag": 1, "de_begriff": "Ausbildungsordnung", "de": "Verordnung des Bundes für einen Beruf, für Büromanagement die BüroMKfAusbV 2025.", "fa_begriff": "آیین‌نامه‌ی آموزش حرفه‌ای (Ausbildungsordnung)", "fa": "مقررات دولت فدرال برای یک حرفه. برای مدیریت اداری این مقررات BüroMKfAusbV 2025 است.", "ru_begriff": "положение о профессиональном обучении (Ausbildungsordnung)", "ru": "Федеральное постановление для одной профессии. Для офисного менеджмента (Büromanagement) это BüroMKfAusbV 2025."}, {"id": 5, "tag": 1, "de_begriff": "Ausbildungsrahmenplan", "de": "Teil der Ausbildungsordnung, gliedert die Inhalte sachlich und zeitlich für alle Betriebe.", "fa_begriff": "برنامه‌ی چارچوب آموزش در شرکت (Ausbildungsrahmenplan)", "fa": "بخشی از آیین‌نامه‌ی آموزش حرفه‌ای. محتواها را از نظر موضوع و زمان برای همه‌ی شرکت‌ها تقسیم‌بندی می‌کند.", "ru_begriff": "рамочный план обучения на предприятии (Ausbildungsrahmenplan)", "ru": "Часть положения о профессиональном обучении. Он распределяет содержание обучения по темам и по времени для всех предприятий."}, {"id": 6, "tag": 1, "de_begriff": "Betrieblicher Ausbildungsplan", "de": "Plan des Betriebs, wann der Auszubildende wo was lernt. Er wird spätestens zu Beginn der Ausbildung erstellt.", "fa_begriff": "برنامه‌ی آموزشی شرکت (Betrieblicher Ausbildungsplan)", "fa": "برنامه‌ی شرکت که نشان می‌دهد کارآموز چه زمانی، کجا و چه چیزی یاد می‌گیرد. این برنامه حداکثر تا شروع آموزش تهیه می‌شود.", "ru_begriff": "план обучения на предприятии (betrieblicher Ausbildungsplan)", "ru": "План предприятия, когда, где и чему учится обучающийся (Azubi). Его составляют не позднее начала обучения."}, {"id": 7, "tag": 1, "de_begriff": "Rahmenlehrplan", "de": "Plan der KMK für den Berufsschulunterricht, für Büromanagement mit 13 Lernfeldern.", "fa_begriff": "برنامه‌ی درسی چارچوب (Rahmenlehrplan)", "fa": "برنامه‌ی KMK برای درس‌های مدرسه‌ی حرفه‌ای (Berufsschule). برای مدیریت اداری با 13 حوزه‌ی یادگیری (Lernfelder).", "ru_begriff": "рамочный учебный план (Rahmenlehrplan)", "ru": "План KMK для занятий в профессиональной школе (Berufsschule). Для офисного менеджмента в нём 13 учебных областей (Lernfelder)."}, {"id": 8, "tag": 1, "de_begriff": "Ausbildender", "de": "Vertragspartner, der zur Ausbildung einstellt, bei uns die Nordholz Büromöbel GmbH.", "fa_begriff": "کارفرمای آموزشی (Ausbildender)", "fa": "طرف قرارداد که فرد را برای آموزش استخدام می‌کند. در مثال ما شرکت Nordholz Büromöbel GmbH.", "ru_begriff": "организатор обучения, работодатель (Ausbildender)", "ru": "Сторона договора, которая принимает на обучение. У нас это Nordholz Büromöbel GmbH."}, {"id": 9, "tag": 1, "de_begriff": "Ausbilder", "de": "Person, die tatsächlich ausbildet und persönlich und fachlich geeignet ist, bei uns Mareike Jansen.", "fa_begriff": "مربی آموزشی (Ausbilder)", "fa": "کسی که در عمل آموزش می‌دهد و از نظر شخصی و تخصصی صلاحیت دارد. در مثال ما Mareike Jansen.", "ru_begriff": "наставник по обучению (Ausbilder)", "ru": "Человек, который на самом деле обучает и подходит для этого лично и профессионально. У нас это Mareike Jansen."}, {"id": 10, "tag": 1, "de_begriff": "AEVO", "de": "Ausbilder-Eignungsverordnung. Sie regelt den Nachweis der berufs- und arbeitspädagogischen Eignung.", "fa_begriff": "AEVO، آیین‌نامه‌ی صلاحیت مربیان (Ausbilder-Eignungsverordnung)", "fa": "آیین‌نامه‌ی صلاحیت مربیان آموزشی. این آیین‌نامه مشخص می‌کند مربی چگونه صلاحیت حرفه‌ای و آموزشی خود را ثابت کند.", "ru_begriff": "AEVO, положение о пригодности наставников (Ausbilder-Eignungsverordnung)", "ru": "Постановление о пригодности наставников. Оно регулирует, как подтвердить профессиональную и производственно-педагогическую пригодность."}, {"id": 11, "tag": 1, "de_begriff": "Zuständige Stelle", "de": "Stelle, die die Ausbildung überwacht, berät und prüft, für Büromanagement die IHK.", "fa_begriff": "نهاد مسئول (Zuständige Stelle)", "fa": "نهادی که بر آموزش نظارت می‌کند، مشاوره می‌دهد و امتحان می‌گیرد. برای مدیریت اداری این نهاد اتاق صنعت و تجارت (IHK) است.", "ru_begriff": "компетентный орган (zuständige Stelle)", "ru": "Орган, который контролирует обучение, консультирует и проводит экзамены. Для офисного менеджмента это IHK (Торгово-промышленная палата)."}, {"id": 12, "tag": 1, "de_begriff": "Gestreckte Abschlussprüfung", "de": "Abschlussprüfung in zwei zeitlich getrennten Teilen, Teil 1 zählt 25 Prozent und Teil 2 zählt 75 Prozent.", "fa_begriff": "امتحان پایانی دو مرحله‌ای (Gestreckte Abschlussprüfung)", "fa": "امتحان پایانی در دو بخش که در زمان‌های جدا برگزار می‌شوند. بخش 1 برابر 25 درصد و بخش 2 برابر 75 درصد نمره حساب می‌شود.", "ru_begriff": "выпускной экзамен из двух частей (gestreckte Abschlussprüfung)", "ru": "Выпускной экзамен из двух частей в разное время. Часть 1 составляет 25 процентов, часть 2 составляет 75 процентов."}, {"id": 13, "tag": 2, "de_begriff": "Berufsausbildungsvertrag", "de": "Vertrag zwischen dem Ausbildenden (Betrieb) und dem Auszubildenden über die Ausbildung in einem anerkannten Beruf (§ 10 BBiG).", "fa_begriff": "قرارداد آموزش حرفه‌ای (Berufsausbildungsvertrag)", "fa": "قرارداد میان کارفرمای آموزشی (شرکت) و کارآموز برای آموزش در یک حرفه‌ی به رسمیت شناخته‌شده (§ 10 BBiG).", "ru_begriff": "договор о профессиональном обучении (Berufsausbildungsvertrag)", "ru": "Договор между организатором обучения (предприятием) и обучающимся об обучении признанной профессии (§ 10 BBiG)."}, {"id": 14, "tag": 2, "de_begriff": "Textform", "de": "Lesbare Erklärung, die gespeichert werden kann, z. B. PDF oder E-Mail. Eine eigenhändige Unterschrift ist nicht nötig.", "fa_begriff": "شکل متنی (Textform)", "fa": "اظهاری خواندنی که می‌توان آن را ذخیره کرد، برای مثال PDF یا ایمیل. امضای دستی لازم نیست.", "ru_begriff": "текстовая форма (Textform)", "ru": "Читаемое заявление, которое можно сохранить, например PDF или электронное письмо. Собственноручная подпись не нужна."}, {"id": 15, "tag": 2, "de_begriff": "Schriftform", "de": "Papier mit eigenhändiger Unterschrift. Für jede Kündigung im Ausbildungsverhältnis Pflicht.", "fa_begriff": "شکل کتبی با امضا (Schriftform)", "fa": "کاغذ با امضای دستی خود شخص. برای هر نوع فسخ در رابطه‌ی آموزشی الزامی است.", "ru_begriff": "письменная форма (Schriftform)", "ru": "Бумажный документ с собственноручной подписью. Она обязательна для любого расторжения договора об обучении (Kündigung)."}, {"id": 16, "tag": 2, "de_begriff": "Vertragsabfassung", "de": "Das Dokument mit dem wesentlichen Inhalt des Ausbildungsvertrags, das der Ausbildende erstellt (§ 11 BBiG).", "fa_begriff": "متن مکتوب قرارداد (Vertragsabfassung)", "fa": "سندی با محتوای اصلی قرارداد آموزشی که کارفرمای آموزشی آن را تهیه می‌کند (§ 11 BBiG).", "ru_begriff": "письменное оформление договора (Vertragsabfassung)", "ru": "Документ с основным содержанием договора об обучении. Его составляет организатор обучения (§ 11 BBiG)."}, {"id": 17, "tag": 2, "de_begriff": "Empfangsnachweis", "de": "Beleg, dass Azubi und gesetzliche Vertreter die Vertragsabfassung erhalten haben. Er wird mit der Vertragskopie bei der IHK eingereicht.", "fa_begriff": "رسید دریافت (Empfangsnachweis)", "fa": "مدرکی که نشان می‌دهد کارآموز و نمایندگان قانونی او متن مکتوب قرارداد را دریافت کرده‌اند. این رسید همراه با نسخه‌ی قرارداد به IHK تحویل داده می‌شود.", "ru_begriff": "подтверждение получения (Empfangsnachweis)", "ru": "Документ о том, что обучающийся и его законные представители получили оформленный договор. Его подают в IHK вместе с копией договора."}, {"id": 18, "tag": 2, "de_begriff": "Verzeichnis der Berufsausbildungsverhältnisse", "de": "Liste bei der IHK, in die jeder Ausbildungsvertrag eingetragen wird (§ 34 BBiG). Für Azubis kostenlos.", "fa_begriff": "فهرست رابطه‌های آموزش حرفه‌ای (Verzeichnis der Berufsausbildungsverhältnisse)", "fa": "فهرستی در IHK که هر قرارداد آموزشی در آن ثبت می‌شود (§ 34 BBiG). برای کارآموزان رایگان است.", "ru_begriff": "реестр договоров о профессиональном обучении (Verzeichnis der Berufsausbildungsverhältnisse)", "ru": "Список в IHK, в который вносят каждый договор об обучении (§ 34 BBiG). Для обучающихся это бесплатно."}, {"id": 19, "tag": 2, "de_begriff": "Probezeit", "de": "Erste Zeit der Ausbildung zum gegenseitigen Kennenlernen, mindestens ein und höchstens vier Monate (§ 20 BBiG).", "fa_begriff": "دوره‌ی آزمایشی (Probezeit)", "fa": "نخستین مدت آموزش برای آشنایی دوطرفه. حداقل یک ماه و حداکثر چهار ماه (§ 20 BBiG).", "ru_begriff": "испытательный срок (Probezeit)", "ru": "Первый период обучения, чтобы стороны познакомились друг с другом. Минимум один и максимум четыре месяца (§ 20 BBiG)."}, {"id": 20, "tag": 2, "de_begriff": "Mindestausbildungsvergütung", "de": "Gesetzliche Untergrenze für die Vergütung. Sie richtet sich nach dem Jahr des Ausbildungsbeginns (§ 17 BBiG).", "fa_begriff": "حداقل حقوق کارآموزی (Mindestausbildungsvergütung)", "fa": "حد پایین قانونی برای حقوق کارآموزی. مبلغ آن به سال شروع آموزش بستگی دارد (§ 17 BBiG).", "ru_begriff": "минимальное вознаграждение за обучение (Mindestausbildungsvergütung)", "ru": "Нижняя граница вознаграждения по закону. Она зависит от года начала обучения (§ 17 BBiG)."}, {"id": 21, "tag": 2, "de_begriff": "Freistellung", "de": "Der Betrieb muss den Azubi für Berufsschule und Prüfungen von der Arbeit befreien (§ 15 BBiG) und die Vergütung weiterzahlen (§ 19 BBiG).", "fa_begriff": "معافیت از کار (Freistellung)", "fa": "شرکت باید کارآموز را برای مدرسه‌ی حرفه‌ای و امتحان‌ها از کار معاف کند (§ 15 BBiG) و حقوق او را همچنان بپردازد (§ 19 BBiG).", "ru_begriff": "освобождение от работы (Freistellung)", "ru": "Предприятие должно освобождать обучающегося от работы для профессиональной школы и экзаменов (§ 15 BBiG) и продолжать платить вознаграждение (§ 19 BBiG)."}, {"id": 22, "tag": 2, "de_begriff": "Wichtiger Grund", "de": "Schwerer Grund, der eine Fortsetzung der Ausbildung unzumutbar macht. Er erlaubt eine Kündigung ohne Frist nach der Probezeit (§ 22 BBiG).", "fa_begriff": "دلیل مهم (Wichtiger Grund)", "fa": "دلیلی جدی که ادامه‌ی آموزش را غیرقابل تحمل می‌کند. این دلیل پس از دوره‌ی آزمایشی اجازه‌ی فسخ بدون مهلت را می‌دهد (§ 22 BBiG).", "ru_begriff": "уважительная причина (wichtiger Grund)", "ru": "Серьёзная причина, из-за которой продолжать обучение невозможно. После испытательного срока она позволяет расторгнуть договор без срока предупреждения (§ 22 BBiG)."}, {"id": 23, "tag": 2, "de_begriff": "Einfaches Zeugnis", "de": "Zeugnis mit Art, Dauer und Ziel der Ausbildung sowie den erworbenen Fertigkeiten, Kenntnissen und Fähigkeiten (§ 16 BBiG).", "fa_begriff": "گواهی ساده (Einfaches Zeugnis)", "fa": "گواهی‌ای که نوع، مدت و هدف آموزش و همچنین مهارت‌ها، دانش و توانایی‌های به‌دست‌آمده را نشان می‌دهد (§ 16 BBiG).", "ru_begriff": "простое свидетельство (einfaches Zeugnis)", "ru": "Свидетельство о виде, продолжительности и цели обучения, а также о полученных умениях, знаниях и способностях (§ 16 BBiG)."}, {"id": 24, "tag": 2, "de_begriff": "Qualifiziertes Zeugnis", "de": "Zeugnis, das auf Verlangen des Azubis zusätzlich Verhalten und Leistung beurteilt (§ 16 BBiG).", "fa_begriff": "گواهی همراه با ارزیابی (Qualifiziertes Zeugnis)", "fa": "گواهی‌ای که به درخواست کارآموز، رفتار و عملکرد او را هم ارزیابی می‌کند (§ 16 BBiG).", "ru_begriff": "квалифицированное свидетельство (qualifiziertes Zeugnis)", "ru": "Свидетельство, которое по просьбе обучающегося дополнительно оценивает поведение и успехи (§ 16 BBiG)."}, {"id": 25, "tag": 3, "de_begriff": "Betriebsrat", "de": "Gewählte Vertretung aller Arbeitnehmer im Betrieb. Bei Nordholz hat er 7 Mitglieder (§ 9 BetrVG).", "fa_begriff": "شورای کارکنان (Betriebsrat)", "fa": "نمایندگی منتخب همه‌ی کارکنان در شرکت. در Nordholz این شورا 7 عضو دارد (§ 9 BetrVG).", "ru_begriff": "производственный совет (Betriebsrat)", "ru": "Выборное представительство всех работников на предприятии. В Nordholz в нём 7 членов (§ 9 BetrVG)."}, {"id": 26, "tag": 3, "de_begriff": "Jugend- und Auszubildendenvertretung (JAV)", "de": "Gewählte Vertretung der Beschäftigten unter 18 Jahren und der Auszubildenden. Sie arbeitet eng mit dem Betriebsrat zusammen (§ 60 BetrVG).", "fa_begriff": "نمایندگی نوجوانان و کارآموزان (Jugend- und Auszubildendenvertretung، JAV)", "fa": "نمایندگی منتخب کارکنان زیر 18 سال و کارآموزان. این نمایندگی همکاری نزدیکی با شورای کارکنان دارد (§ 60 BetrVG).", "ru_begriff": "представительство молодёжи и обучающихся (Jugend- und Auszubildendenvertretung, JAV)", "ru": "Выборное представительство работников младше 18 лет и обучающихся. Оно тесно сотрудничает с производственным советом (§ 60 BetrVG)."}, {"id": 27, "tag": 3, "de_begriff": "Wahlberechtigung", "de": "Das Recht, bei einer Wahl die eigene Stimme abzugeben. Für die JAV alle unter 18 und alle Auszubildenden.", "fa_begriff": "حق رأی دادن (Wahlberechtigung)", "fa": "حق اینکه فرد در انتخابات رأی خود را بدهد. برای JAV همه‌ی افراد زیر 18 سال و همه‌ی کارآموزان این حق را دارند.", "ru_begriff": "право голосовать (Wahlberechtigung)", "ru": "Право отдать свой голос на выборах. Для JAV это все младше 18 лет и все обучающиеся."}, {"id": 28, "tag": 3, "de_begriff": "Wählbarkeit", "de": "Das Recht, gewählt zu werden. Für die JAV alle unter 25 Jahren und alle Auszubildenden, aber keine Mitglieder des Betriebsrats.", "fa_begriff": "حق انتخاب شدن (Wählbarkeit)", "fa": "حق اینکه فرد انتخاب شود. برای JAV همه‌ی افراد زیر 25 سال و همه‌ی کارآموزان این حق را دارند، اما اعضای شورای کارکنان این حق را ندارند.", "ru_begriff": "право быть избранным (Wählbarkeit)", "ru": "Право быть избранным. Для JAV это все младше 25 лет и все обучающиеся, но не члены производственного совета."}, {"id": 29, "tag": 3, "de_begriff": "Übernahmeschutz", "de": "Schutz für Auszubildende in JAV oder Betriebsrat. Verlangen sie rechtzeitig schriftlich die Weiterbeschäftigung, entsteht ein unbefristetes Arbeitsverhältnis (§ 78a BetrVG).", "fa_begriff": "حمایت در استخدام پس از آموزش (Übernahmeschutz)", "fa": "حمایت از کارآموزانی که عضو JAV یا شورای کارکنان هستند. اگر آن‌ها به‌موقع و به‌صورت کتبی ادامه‌ی کار را درخواست کنند، یک رابطه‌ی کاری بدون محدودیت زمانی ایجاد می‌شود (§ 78a BetrVG).", "ru_begriff": "защита при переходе на работу (Übernahmeschutz)", "ru": "Защита для обучающихся в JAV или в производственном совете. Если они вовремя письменно требуют оставить их на работе, возникают бессрочные трудовые отношения (§ 78a BetrVG)."}, {"id": 30, "tag": 3, "de_begriff": "Jugendlicher", "de": "Wer 15, aber noch nicht 18 Jahre alt ist. Wer noch nicht 15 ist, gilt als Kind (§ 2 JArbSchG).", "fa_begriff": "نوجوان (Jugendlicher)", "fa": "کسی که 15 سال دارد اما هنوز 18 ساله نشده است. کسی که هنوز 15 ساله نشده، کودک به حساب می‌آید (§ 2 JArbSchG).", "ru_begriff": "подросток (Jugendlicher)", "ru": "Тот, кому уже 15 лет, но ещё нет 18. Тот, кому ещё нет 15, считается ребёнком (§ 2 JArbSchG)."}, {"id": 31, "tag": 3, "de_begriff": "Schichtzeit", "de": "Arbeitszeit plus Ruhepausen, also die ganze Zeit vom Arbeitsbeginn bis zum Feierabend. Höchstens 10 Stunden (§ 12 JArbSchG).", "fa_begriff": "زمان شیفت (Schichtzeit)", "fa": "زمان کار به‌علاوه‌ی استراحت‌ها، یعنی کل زمان از شروع کار تا پایان کار. حداکثر 10 ساعت (§ 12 JArbSchG).", "ru_begriff": "время смены (Schichtzeit)", "ru": "Рабочее время вместе с перерывами на отдых, то есть всё время от начала работы до её окончания. Максимум 10 часов (§ 12 JArbSchG)."}, {"id": 32, "tag": 3, "de_begriff": "Ruhepause", "de": "Eine im Voraus feste Unterbrechung der Arbeit von mindestens 15 Minuten (§ 11 JArbSchG).", "fa_begriff": "استراحت (Ruhepause)", "fa": "وقفه‌ای در کار که از قبل مشخص شده و حداقل 15 دقیقه است (§ 11 JArbSchG).", "ru_begriff": "перерыв на отдых (Ruhepause)", "ru": "Заранее установленный перерыв в работе минимум 15 минут (§ 11 JArbSchG)."}, {"id": 33, "tag": 3, "de_begriff": "Nachtruhe", "de": "Jugendliche dürfen grundsätzlich nur zwischen 6 und 20 Uhr arbeiten (§ 14 JArbSchG).", "fa_begriff": "استراحت شبانه (Nachtruhe)", "fa": "نوجوانان در اصل فقط بین ساعت 6 تا 20 اجازه‌ی کار دارند (§ 14 JArbSchG).", "ru_begriff": "ночной отдых (Nachtruhe)", "ru": "Подростки, как правило, могут работать только с 6 до 20 часов (§ 14 JArbSchG)."}, {"id": 34, "tag": 3, "de_begriff": "Werktag", "de": "Jeder Tag außer Sonntag und Feiertag, also auch der Samstag. Urlaub im JArbSchG wird in Werktagen angegeben.", "fa_begriff": "روز کاری (Werktag)", "fa": "هر روز به جز یکشنبه و روزهای تعطیل رسمی، یعنی شنبه هم روز کاری است. مرخصی در JArbSchG بر اساس روز کاری بیان می‌شود.", "ru_begriff": "рабочий день по закону (Werktag)", "ru": "Каждый день, кроме воскресенья и праздника, то есть суббота тоже. Отпуск по JArbSchG указывают в таких днях."}, {"id": 35, "tag": 3, "de_begriff": "Erstuntersuchung", "de": "Ärztliche Untersuchung vor dem Beginn der Beschäftigung. Sie darf höchstens 14 Monate alt sein (§ 32 JArbSchG).", "fa_begriff": "معاینه‌ی اول (Erstuntersuchung)", "fa": "معاینه‌ی پزشکی پیش از شروع کار. این معاینه حداکثر می‌تواند 14 ماه پیش انجام شده باشد (§ 32 JArbSchG).", "ru_begriff": "первичный медицинский осмотр (Erstuntersuchung)", "ru": "Медицинский осмотр до начала работы. Он должен быть сделан не больше 14 месяцев назад (§ 32 JArbSchG)."}, {"id": 36, "tag": 3, "de_begriff": "Nachuntersuchung", "de": "Zweite ärztliche Untersuchung ein Jahr nach Beginn der Beschäftigung. Fehlt die Bescheinigung nach 14 Monaten, gilt ein Beschäftigungsverbot (§ 33 JArbSchG).", "fa_begriff": "معاینه‌ی پیگیری (Nachuntersuchung)", "fa": "دومین معاینه‌ی پزشکی یک سال پس از شروع کار. اگر گواهی آن پس از 14 ماه وجود نداشته باشد، ممنوعیت کار اعمال می‌شود (§ 33 JArbSchG).", "ru_begriff": "повторный медицинский осмотр (Nachuntersuchung)", "ru": "Второй медицинский осмотр через год после начала работы. Если через 14 месяцев справки нет, работать запрещено (§ 33 JArbSchG)."}, {"id": 37, "tag": 4, "de_begriff": "Lebenslanges Lernen", "de": "Lernen im ganzen Berufsleben, nicht nur in Schule und Ausbildung. Es kann geplant in Kursen oder nebenbei bei der Arbeit stattfinden.", "fa_begriff": "یادگیری مادام‌العمر (Lebenslanges Lernen)", "fa": "یادگیری در تمام دوران کاری، نه فقط در مدرسه و آموزش حرفه‌ای. این یادگیری می‌تواند برنامه‌ریزی‌شده در دوره‌ها یا در کنار کار روزانه انجام شود.", "ru_begriff": "обучение в течение всей жизни (lebenslanges Lernen)", "ru": "Обучение в течение всей трудовой жизни, а не только в школе и при профессиональном обучении. Оно может проходить по плану на курсах или попутно во время работы."}, {"id": 38, "tag": 4, "de_begriff": "Weiterbildung", "de": "Oberbegriff für alles berufliche Lernen nach einer ersten Ausbildung, zum Beispiel Fortbildung und Umschulung.", "fa_begriff": "آموزش تکمیلی (Weiterbildung)", "fa": "اصطلاح کلی برای همه‌ی یادگیری‌های حرفه‌ای پس از اولین آموزش حرفه‌ای، برای مثال دوره‌ی ارتقای حرفه‌ای (Fortbildung) و بازآموزی (Umschulung).", "ru_begriff": "дальнейшее профессиональное образование (Weiterbildung)", "ru": "Общее понятие для всего профессионального обучения после первого профессионального образования, например повышение квалификации и переобучение."}, {"id": 39, "tag": 4, "de_begriff": "Anpassungsfortbildung", "de": "Fortbildung, die vorhandenes Können erhält und an neue Anforderungen anpasst, zum Beispiel eine Schulung zu neuer Software (§ 1 Abs. 4 Nr. 1 BBiG).", "fa_begriff": "دوره‌ی به‌روزرسانی مهارت (Anpassungsfortbildung)", "fa": "دوره‌ای که توانایی‌های موجود را حفظ می‌کند و با نیازهای جدید هماهنگ می‌کند، برای مثال آموزش یک نرم‌افزار جدید (§ 1 Abs. 4 Nr. 1 BBiG).", "ru_begriff": "повышение квалификации для адаптации (Anpassungsfortbildung)", "ru": "Обучение, которое сохраняет имеющиеся умения и приспосабливает их к новым требованиям, например курс по новой программе (§ 1 Abs. 4 Nr. 1 BBiG)."}, {"id": 40, "tag": 4, "de_begriff": "Aufstiegsfortbildung", "de": "Fortbildung für den beruflichen Aufstieg mit einem höheren Abschluss, zum Beispiel Bachelor Professional (§ 1 Abs. 4 Nr. 2 BBiG).", "fa_begriff": "دوره‌ی ارتقای شغلی (Aufstiegsfortbildung)", "fa": "دوره‌ای برای پیشرفت شغلی با یک مدرک بالاتر، برای مثال Bachelor Professional (§ 1 Abs. 4 Nr. 2 BBiG).", "ru_begriff": "повышение квалификации для карьерного роста (Aufstiegsfortbildung)", "ru": "Обучение для продвижения по работе с более высоким дипломом, например Bachelor Professional (§ 1 Abs. 4 Nr. 2 BBiG)."}, {"id": 41, "tag": 4, "de_begriff": "Umschulung", "de": "Berufsbildung, die zu einer anderen beruflichen Tätigkeit befähigt, also zu einem neuen Beruf (§ 1 Abs. 5 BBiG).", "fa_begriff": "بازآموزی حرفه‌ای (Umschulung)", "fa": "آموزش حرفه‌ای که فرد را برای یک فعالیت شغلی دیگر، یعنی یک حرفه‌ی جدید، آماده می‌کند (§ 1 Abs. 5 BBiG).", "ru_begriff": "переобучение (Umschulung)", "ru": "Профессиональное обучение, которое готовит к другой профессиональной деятельности, то есть к новой профессии (§ 1 Abs. 5 BBiG)."}, {"id": 42, "tag": 4, "de_begriff": "Job-Rotation", "de": "Planmäßiger Wechsel zwischen verschiedenen Arbeitsplätzen, damit man mehr Abläufe kennenlernt.", "fa_begriff": "چرخش شغلی (Job-Rotation)", "fa": "جابه‌جایی برنامه‌ریزی‌شده بین محل‌های کاری مختلف، تا فرد با روندهای کاری بیشتری آشنا شود.", "ru_begriff": "ротация рабочих мест (Job-Rotation)", "ru": "Плановая смена разных рабочих мест, чтобы узнать больше рабочих процессов."}, {"id": 43, "tag": 4, "de_begriff": "Job-Enlargement", "de": "Aufgabenerweiterung. Man bekommt zusätzliche Aufgaben auf dem gleichen Niveau.", "fa_begriff": "گسترش شغل (Job-Enlargement)", "fa": "افزایش وظایف. فرد وظایف بیشتری در همان سطح دریافت می‌کند.", "ru_begriff": "расширение задач (Job-Enlargement)", "ru": "Расширение круга задач. Работник получает дополнительные задачи того же уровня."}, {"id": 44, "tag": 4, "de_begriff": "Job-Enrichment", "de": "Aufgabenbereicherung. Man bekommt anspruchsvollere Aufgaben mit mehr Verantwortung und Entscheidungsfreiheit.", "fa_begriff": "غنی‌سازی شغل (Job-Enrichment)", "fa": "غنی‌تر کردن وظایف. فرد وظایف دشوارتری با مسئولیت بیشتر و آزادی بیشتر در تصمیم‌گیری دریافت می‌کند.", "ru_begriff": "обогащение задач (Job-Enrichment)", "ru": "Обогащение работы. Работник получает более сложные задачи с большей ответственностью и свободой принимать решения."}, {"id": 45, "tag": 4, "de_begriff": "Mentoring", "de": "Eine erfahrene Person (Mentor) begleitet und berät eine weniger erfahrene Person (Mentee) über längere Zeit.", "fa_begriff": "راهنمایی و همراهی (Mentoring)", "fa": "یک فرد باتجربه (Mentor) یک فرد کم‌تجربه‌تر (Mentee) را برای مدتی طولانی همراهی و راهنمایی می‌کند.", "ru_begriff": "наставничество (Mentoring)", "ru": "Опытный человек (ментор) долгое время сопровождает и консультирует менее опытного человека (менти)."}, {"id": 46, "tag": 4, "de_begriff": "Bachelor Professional", "de": "Abschluss der zweiten Fortbildungsstufe nach § 53a BBiG mit mindestens 1.200 Lernstunden, zum Beispiel Bilanzbuchhalter.", "fa_begriff": "Bachelor Professional، مدرک ارتقای حرفه‌ای سطح دوم", "fa": "مدرک سطح دوم دوره‌های ارتقای حرفه‌ای طبق § 53a BBiG با حداقل 1.200 ساعت یادگیری، برای مثال حسابدار ترازنامه (Bilanzbuchhalter).", "ru_begriff": "профессиональный бакалавр (Bachelor Professional)", "ru": "Диплом второй ступени повышения квалификации по § 53a BBiG, минимум 1.200 учебных часов, например бухгалтер по балансу (Bilanzbuchhalter)."}, {"id": 47, "tag": 4, "de_begriff": "Aufstiegs-BAföG", "de": "Staatliche Förderung für Aufstiegsfortbildungen nach dem AFBG. Lehrgangs- und Prüfungsgebühren bis 15.000 € werden zur Hälfte als Zuschuss gezahlt.", "fa_begriff": "کمک‌هزینه‌ی دولتی برای ارتقای شغلی (Aufstiegs-BAföG)", "fa": "حمایت مالی دولت برای دوره‌های ارتقای شغلی طبق AFBG. نیمی از هزینه‌های دوره و امتحان تا 15.000 € به‌صورت کمک بلاعوض پرداخت می‌شود.", "ru_begriff": "государственная поддержка для карьерного роста (Aufstiegs-BAföG)", "ru": "Государственная поддержка повышения квалификации для карьерного роста по закону AFBG. Плату за курсы и экзамены до 15.000 € наполовину оплачивают как безвозвратную субсидию."}, {"id": 48, "tag": 4, "de_begriff": "Bildungsurlaub", "de": "Bezahlte Freistellung für Weiterbildung. Die Regeln stehen in Gesetzen der Bundesländer, nicht in einem Bundesgesetz.", "fa_begriff": "مرخصی آموزشی (Bildungsurlaub)", "fa": "معافیت از کار با حقوق برای آموزش تکمیلی. قواعد آن در قوانین ایالت‌ها آمده است، نه در یک قانون فدرال.", "ru_begriff": "учебный отпуск (Bildungsurlaub)", "ru": "Оплачиваемое освобождение от работы для дальнейшего обучения. Правила установлены в законах федеральных земель, а не в федеральном законе."}, {"id": 49, "tag": 5, "de_begriff": "Bedürfnis", "de": "Das Gefühl eines Mangels und der Wunsch, diesen Mangel zu beseitigen, z. B. Hunger oder der Wunsch nach einem bequemen Bürostuhl.", "fa_begriff": "نیاز (Bedürfnis)", "fa": "احساس کمبود و خواستِ برطرف کردن این کمبود، برای مثال گرسنگی یا خواستن یک صندلی اداری راحت.", "ru_begriff": "потребность (Bedürfnis)", "ru": "Чувство нехватки чего-то и желание устранить эту нехватку, например голод или желание иметь удобное офисное кресло."}, {"id": 50, "tag": 5, "de_begriff": "Wirtschaftliches Gut", "de": "Ein knappes Mittel zur Befriedigung von Bedürfnissen, das einen Preis hat, z. B. ein Schreibtisch oder eine Beratung.", "fa_begriff": "کالای اقتصادی (Wirtschaftliches Gut)", "fa": "وسیله‌ای کمیاب برای برآوردن نیازها که قیمت دارد، برای مثال یک میز کار یا یک مشاوره.", "ru_begriff": "экономическое благо (wirtschaftliches Gut)", "ru": "Ограниченное средство для удовлетворения потребностей, у которого есть цена, например письменный стол или консультация."}, {"id": 51, "tag": 5, "de_begriff": "Primärer Sektor", "de": "Urproduktion. Rohstoffe werden aus der Natur gewonnen, z. B. Landwirtschaft, Forstwirtschaft, Fischerei.", "fa_begriff": "بخش اول اقتصاد (Primärer Sektor)", "fa": "تولید اولیه. مواد خام از طبیعت به دست می‌آیند، برای مثال کشاورزی، جنگلداری و ماهیگیری.", "ru_begriff": "первичный сектор (primärer Sektor)", "ru": "Добыча сырья (Urproduktion). Сырьё получают из природы, например сельское хозяйство, лесное хозяйство, рыболовство."}, {"id": 52, "tag": 5, "de_begriff": "Sekundärer Sektor", "de": "Verarbeitung. Rohstoffe werden zu Produkten verarbeitet, z. B. Industrie und Handwerk.", "fa_begriff": "بخش دوم اقتصاد (Sekundärer Sektor)", "fa": "فرآوری. مواد خام به محصول تبدیل می‌شوند، برای مثال صنعت و پیشه‌وری.", "ru_begriff": "вторичный сектор (sekundärer Sektor)", "ru": "Переработка. Сырьё перерабатывают в продукты, например промышленность и ремесло."}, {"id": 53, "tag": 5, "de_begriff": "Tertiärer Sektor", "de": "Dienstleistungen, z. B. Handel, Banken, Versicherungen, Verkehr, Beratung.", "fa_begriff": "بخش سوم اقتصاد (Tertiärer Sektor)", "fa": "خدمات، برای مثال بازرگانی، بانک‌ها، بیمه‌ها، حمل‌ونقل و مشاوره.", "ru_begriff": "третичный сектор (tertiärer Sektor)", "ru": "Услуги, например торговля, банки, страхование, транспорт, консультации."}, {"id": 54, "tag": 5, "de_begriff": "Erwerbswirtschaftlicher Betrieb", "de": "Betrieb, der vor allem Gewinn erzielen will. Der Gewinn steht den Eigentümern zu.", "fa_begriff": "بنگاه سودمحور (Erwerbswirtschaftlicher Betrieb)", "fa": "شرکتی که پیش از هر چیز می‌خواهد سود به دست آورد. سود متعلق به مالکان است.", "ru_begriff": "коммерческое предприятие (erwerbswirtschaftlicher Betrieb)", "ru": "Предприятие, которое прежде всего хочет получать прибыль. Прибыль принадлежит владельцам."}, {"id": 55, "tag": 5, "de_begriff": "Gemeinwirtschaftlicher Betrieb", "de": "Betrieb, der vor allem den Bedarf der Allgemeinheit decken will, z. B. Wasserversorgung. Er arbeitet meist kostendeckend.", "fa_begriff": "بنگاه عام‌المنفعه (Gemeinwirtschaftlicher Betrieb)", "fa": "شرکتی که پیش از هر چیز می‌خواهد نیاز عموم مردم را تأمین کند، برای مثال تأمین آب. این شرکت معمولاً طوری کار می‌کند که فقط هزینه‌هایش پوشش داده شود.", "ru_begriff": "предприятие для общественных нужд (gemeinwirtschaftlicher Betrieb)", "ru": "Предприятие, которое прежде всего хочет покрывать потребности общества, например водоснабжение. Обычно оно работает так, чтобы только покрыть свои затраты."}, {"id": 56, "tag": 5, "de_begriff": "Genossenschaft", "de": "Zusammenschluss von Mitgliedern, der die Mitglieder wirtschaftlich fördert, z. B. eine Volksbank oder eine Wohnungsbaugenossenschaft.", "fa_begriff": "تعاونی (Genossenschaft)", "fa": "اتحادیه‌ای از اعضا که از نظر اقتصادی به اعضای خود کمک می‌کند، برای مثال یک Volksbank یا یک تعاونی مسکن.", "ru_begriff": "кооператив (Genossenschaft)", "ru": "Объединение членов, которое экономически поддерживает своих членов, например Volksbank или жилищный кооператив."}, {"id": 57, "tag": 5, "de_begriff": "Elementarfaktoren", "de": "Die drei Grundfaktoren der Leistungserstellung nach Gutenberg, also ausführende Arbeit, Betriebsmittel und Werkstoffe.", "fa_begriff": "عوامل پایه‌ای تولید (Elementarfaktoren)", "fa": "سه عامل اصلی تولید کالا و خدمات به نظر گوتنبرگ (Gutenberg)، یعنی کار اجرایی، ابزار و تجهیزات تولید (Betriebsmittel) و مواد اولیه (Werkstoffe).", "ru_begriff": "элементарные факторы (Elementarfaktoren)", "ru": "Три основных фактора создания продукции по Гутенбергу (Gutenberg), то есть исполнительный труд, средства производства и материалы."}, {"id": 58, "tag": 5, "de_begriff": "Dispositiver Faktor", "de": "Leitende Arbeit. Sie plant, leitet, organisiert und kontrolliert den Einsatz der Elementarfaktoren.", "fa_begriff": "عامل مدیریتی (Dispositiver Faktor)", "fa": "کار مدیریتی. این کار به‌کارگیری عوامل پایه‌ای تولید را برنامه‌ریزی، هدایت، سازمان‌دهی و کنترل می‌کند.", "ru_begriff": "диспозитивный фактор (dispositiver Faktor)", "ru": "Руководящий труд. Он планирует, руководит, организует и контролирует использование элементарных факторов."}, {"id": 59, "tag": 5, "de_begriff": "Ökonomisches Prinzip", "de": "Regel für vernünftiges Wirtschaften. Entweder mit festen Mitteln das größte Ergebnis (Maximalprinzip) oder ein festes Ergebnis mit den geringsten Mitteln (Minimalprinzip).", "fa_begriff": "اصل اقتصادی (Ökonomisches Prinzip)", "fa": "قاعده‌ای برای فعالیت اقتصادی معقول. یا با منابع ثابت بیشترین نتیجه به دست می‌آید (اصل حداکثر، Maximalprinzip)، یا یک نتیجه‌ی ثابت با کمترین منابع (اصل حداقل، Minimalprinzip).", "ru_begriff": "экономический принцип (ökonomisches Prinzip)", "ru": "Правило разумного хозяйствования. Либо с заданными средствами получить наибольший результат (принцип максимума, Maximalprinzip), либо получить заданный результат с наименьшими средствами (принцип минимума, Minimalprinzip)."}, {"id": 60, "tag": 5, "de_begriff": "Produktivität", "de": "Mengenverhältnis von Ausbringungsmenge zu Einsatzmenge, z. B. Stühle je Arbeitsstunde.", "fa_begriff": "بهره‌وری (Produktivität)", "fa": "نسبت مقدار تولید به مقدار منابع به‌کاررفته، برای مثال تعداد صندلی در هر ساعت کار.", "ru_begriff": "производительность (Produktivität)", "ru": "Соотношение количества выпуска и количества затрат, например стулья за один рабочий час."}, {"id": 61, "tag": 6, "de_begriff": "Arbeitsteilung", "de": "Eine große Aufgabe wird in Teilaufgaben zerlegt. Verschiedene Personen, Betriebe oder Länder übernehmen je einen Teil.", "fa_begriff": "تقسیم کار (Arbeitsteilung)", "fa": "یک کار بزرگ به بخش‌های کوچک‌تر تقسیم می‌شود. افراد، شرکت‌ها یا کشورهای مختلف هر کدام یک بخش را بر عهده می‌گیرند.", "ru_begriff": "разделение труда (Arbeitsteilung)", "ru": "Большую задачу делят на частичные задачи. Разные люди, предприятия или страны берут на себя каждый свою часть."}, {"id": 62, "tag": 6, "de_begriff": "Wertschöpfungskette", "de": "Alle Stufen vom Rohstoff bis zum fertigen Produkt beim Kunden. Jede Stufe fügt dem Produkt Wert hinzu.", "fa_begriff": "زنجیره‌ی ارزش (Wertschöpfungskette)", "fa": "همه‌ی مراحل از ماده‌ی خام تا محصول نهایی نزد مشتری. هر مرحله به محصول ارزش اضافه می‌کند.", "ru_begriff": "цепочка создания стоимости (Wertschöpfungskette)", "ru": "Все этапы от сырья до готового продукта у клиента. Каждый этап добавляет продукту стоимость."}, {"id": 63, "tag": 6, "de_begriff": "Wirtschaftskreislauf", "de": "Modell, das zeigt, wie Güter und Geld zwischen Haushalten, Unternehmen, Staat, Banken und Ausland fließen.", "fa_begriff": "چرخه‌ی اقتصادی (Wirtschaftskreislauf)", "fa": "مدلی که نشان می‌دهد کالاها و پول چگونه بین خانوارها، شرکت‌ها، دولت، بانک‌ها و کشورهای خارجی جریان دارند.", "ru_begriff": "экономический кругооборот (Wirtschaftskreislauf)", "ru": "Модель, которая показывает, как товары и деньги движутся между домохозяйствами, предприятиями, государством, банками и заграницей."}, {"id": 64, "tag": 6, "de_begriff": "Güterstrom", "de": "Fluss von Waren und Leistungen, zum Beispiel Arbeitskraft oder Büromöbel.", "fa_begriff": "جریان کالا (Güterstrom)", "fa": "جریان کالاها و خدمات، برای مثال نیروی کار یا مبلمان اداری.", "ru_begriff": "поток благ (Güterstrom)", "ru": "Движение товаров и услуг, например рабочей силы или офисной мебели."}, {"id": 65, "tag": 6, "de_begriff": "Geldstrom", "de": "Fluss von Geld, zum Beispiel Lohn, Kaufpreis oder Steuern. Er läuft entgegengesetzt zum Güterstrom.", "fa_begriff": "جریان پول (Geldstrom)", "fa": "جریان پول، برای مثال دستمزد، قیمت خرید یا مالیات. این جریان در جهت مخالف جریان کالا حرکت می‌کند.", "ru_begriff": "денежный поток (Geldstrom)", "ru": "Движение денег, например зарплаты, цены покупки или налогов. Он идёт в обратном направлении по сравнению с потоком благ."}, {"id": 66, "tag": 6, "de_begriff": "Unternehmensleitbild", "de": "Schriftliche Aussage, wofür ein Unternehmen steht, welche Werte es hat und wie es handeln will.", "fa_begriff": "منشور شرکت (Unternehmensleitbild)", "fa": "بیانیه‌ای مکتوب که نشان می‌دهد یک شرکت نماینده‌ی چه چیزی است، چه ارزش‌هایی دارد و چگونه می‌خواهد عمل کند.", "ru_begriff": "миссия и ценности предприятия (Unternehmensleitbild)", "ru": "Письменное заявление о том, за что выступает предприятие, какие у него ценности и как оно хочет действовать."}, {"id": 67, "tag": 6, "de_begriff": "Zielharmonie", "de": "Wenn ein Ziel erreicht wird, hilft das auch einem anderen Ziel.", "fa_begriff": "هماهنگی اهداف (Zielharmonie)", "fa": "وقتی رسیدن به یک هدف به هدف دیگری هم کمک می‌کند.", "ru_begriff": "гармония целей (Zielharmonie)", "ru": "Если достигается одна цель, это помогает и другой цели."}, {"id": 68, "tag": 6, "de_begriff": "Zielkonflikt", "de": "Wenn ein Ziel erreicht wird, behindert das ein anderes Ziel.", "fa_begriff": "تعارض اهداف (Zielkonflikt)", "fa": "وقتی رسیدن به یک هدف مانع هدف دیگری می‌شود.", "ru_begriff": "конфликт целей (Zielkonflikt)", "ru": "Если достигается одна цель, это мешает другой цели."}, {"id": 69, "tag": 6, "de_begriff": "SMART-Ziel", "de": "Ziel, das spezifisch, messbar, attraktiv, realistisch und terminiert ist.", "fa_begriff": "هدف SMART (SMART-Ziel)", "fa": "هدفی که مشخص، قابل اندازه‌گیری، جذاب، واقع‌بینانه و دارای زمان‌بندی است.", "ru_begriff": "SMART-цель (SMART-Ziel)", "ru": "Цель, которая конкретная (spezifisch), измеримая (messbar), привлекательная (attraktiv), реалистичная (realistisch) и с установленным сроком (terminiert)."}, {"id": 70, "tag": 6, "de_begriff": "Umsatzrentabilität", "de": "Kennzahl. Gewinn geteilt durch Umsatz mal 100. Sie zeigt, wie viel Gewinn von 100 € Umsatz bleibt.", "fa_begriff": "بازده فروش (Umsatzrentabilität)", "fa": "یک شاخص. سود تقسیم بر فروش، ضرب در 100. نشان می‌دهد از هر 100 € فروش چه مقدار سود باقی می‌ماند.", "ru_begriff": "рентабельность продаж (Umsatzrentabilität)", "ru": "Показатель. Прибыль делят на выручку и умножают на 100. Он показывает, сколько прибыли остаётся от 100 € выручки."}, {"id": 71, "tag": 6, "de_begriff": "Eigenkapitalrentabilität", "de": "Kennzahl. Gewinn geteilt durch Eigenkapital mal 100. Sie zeigt, wie gut sich das Geld der Eigentümer verzinst.", "fa_begriff": "بازده سرمایه‌ی مالکان (Eigenkapitalrentabilität)", "fa": "یک شاخص. سود تقسیم بر سرمایه‌ی مالکان (Eigenkapital)، ضرب در 100. نشان می‌دهد پول مالکان چقدر خوب سود می‌دهد.", "ru_begriff": "рентабельность собственного капитала (Eigenkapitalrentabilität)", "ru": "Показатель. Прибыль делят на собственный капитал и умножают на 100. Он показывает, насколько хорошо приносят проценты деньги владельцев."}, {"id": 72, "tag": 6, "de_begriff": "Nachhaltigkeit", "de": "Wirtschaften, das ökologisch verträglich, sozial gerecht und wirtschaftlich leistungsfähig ist, damit auch künftige Generationen gut leben können.", "fa_begriff": "پایداری (Nachhaltigkeit)", "fa": "فعالیت اقتصادی که برای محیط زیست قابل تحمل، از نظر اجتماعی عادلانه و از نظر اقتصادی کارآمد باشد، تا نسل‌های آینده هم بتوانند زندگی خوبی داشته باشند.", "ru_begriff": "устойчивость, устойчивое развитие (Nachhaltigkeit)", "ru": "Хозяйствование, которое безопасно для природы, социально справедливо и экономически эффективно, чтобы и будущие поколения могли хорошо жить."}, {"id": 73, "tag": 7, "de_begriff": "Aufbauorganisation", "de": "Ordnet die Aufgaben des Betriebs Stellen und Abteilungen zu und legt fest, wer wem unterstellt ist.", "fa_begriff": "سازمان ساختاری (Aufbauorganisation)", "fa": "وظایف شرکت را به پست‌ها و بخش‌ها اختصاص می‌دهد و مشخص می‌کند چه کسی زیر نظر چه کسی است.", "ru_begriff": "организационная структура (Aufbauorganisation)", "ru": "Распределяет задачи предприятия по должностям и отделам и устанавливает, кто кому подчиняется."}, {"id": 74, "tag": 7, "de_begriff": "Ablauforganisation", "de": "Regelt, in welcher Reihenfolge, wann, wo und womit die Arbeitsschritte erledigt werden.", "fa_begriff": "سازمان فرایندی (Ablauforganisation)", "fa": "مشخص می‌کند مراحل کار به چه ترتیب، چه زمانی، کجا و با چه وسیله‌ای انجام شوند.", "ru_begriff": "организация рабочих процессов (Ablauforganisation)", "ru": "Устанавливает, в какой последовательности, когда, где и с помощью чего выполняются рабочие шаги."}, {"id": 75, "tag": 7, "de_begriff": "Aufgabenanalyse", "de": "Die Gesamtaufgabe des Betriebs wird in viele kleine Teilaufgaben zerlegt.", "fa_begriff": "تحلیل وظایف (Aufgabenanalyse)", "fa": "وظیفه‌ی کلی شرکت به وظایف کوچک زیادی تقسیم می‌شود.", "ru_begriff": "анализ задач (Aufgabenanalyse)", "ru": "Общую задачу предприятия делят на много маленьких частичных задач."}, {"id": 76, "tag": 7, "de_begriff": "Aufgabensynthese", "de": "Passende Teilaufgaben werden zu Stellen und Stellen zu Abteilungen zusammengefasst.", "fa_begriff": "ترکیب وظایف (Aufgabensynthese)", "fa": "وظایف کوچکِ مناسب در قالب پست‌ها جمع می‌شوند و پست‌ها در قالب بخش‌ها.", "ru_begriff": "синтез задач (Aufgabensynthese)", "ru": "Подходящие частичные задачи объединяют в должности, а должности объединяют в отделы."}, {"id": 77, "tag": 7, "de_begriff": "Stelle", "de": "Kleinste organisatorische Einheit. Ein fester Aufgabenbereich für eine Person, unabhängig davon, wer die Stelle gerade besetzt.", "fa_begriff": "پست سازمانی (Stelle)", "fa": "کوچک‌ترین واحد سازمانی. یک حوزه‌ی کاری ثابت برای یک نفر، مستقل از اینکه چه کسی در حال حاضر این پست را دارد.", "ru_begriff": "должность, штатное место (Stelle)", "ru": "Самая маленькая организационная единица. Постоянный круг задач для одного человека, независимо от того, кто сейчас занимает эту должность."}, {"id": 78, "tag": 7, "de_begriff": "Stellenbeschreibung", "de": "Schriftliche Beschreibung einer Stelle mit Ziel, Aufgaben, Befugnissen, Vorgesetzten und Anforderungen.", "fa_begriff": "شرح شغل (Stellenbeschreibung)", "fa": "توضیح مکتوب یک پست با هدف، وظایف، اختیارات، مدیران و شرایط لازم.", "ru_begriff": "должностная инструкция (Stellenbeschreibung)", "ru": "Письменное описание должности с целью, задачами, полномочиями, руководителями и требованиями."}, {"id": 79, "tag": 7, "de_begriff": "Instanz", "de": "Stelle mit Leitungsaufgaben und Weisungsrecht gegenüber anderen Stellen, zum Beispiel eine Abteilungsleitung.", "fa_begriff": "پست مدیریتی (Instanz)", "fa": "پستی با وظایف مدیریتی و حق دستور دادن به پست‌های دیگر، برای مثال مدیریت یک بخش.", "ru_begriff": "руководящая должность (Instanz)", "ru": "Должность с задачами руководства и правом давать указания другим должностям, например руководство отдела."}, {"id": 80, "tag": 7, "de_begriff": "Abteilung", "de": "Mehrere Stellen, die unter einer Leitung (Instanz) zusammengefasst sind.", "fa_begriff": "بخش (Abteilung)", "fa": "چند پست که زیر یک مدیریت (Instanz) جمع شده‌اند.", "ru_begriff": "отдел (Abteilung)", "ru": "Несколько должностей, которые объединены под одним руководством (Instanz)."}, {"id": 81, "tag": 7, "de_begriff": "Stabsstelle", "de": "Stelle, die eine Instanz berät und unterstützt, aber anderen Stellen keine Weisungen geben darf.", "fa_begriff": "پست مشاوره‌ای (Stabsstelle)", "fa": "پستی که به یک پست مدیریتی مشاوره و کمک می‌دهد، اما اجازه ندارد به پست‌های دیگر دستور بدهد.", "ru_begriff": "штабная должность (Stabsstelle)", "ru": "Должность, которая консультирует и поддерживает руководящую должность (Instanz), но не может давать указания другим должностям."}, {"id": 82, "tag": 7, "de_begriff": "Organigramm", "de": "Zeichnung der Aufbauorganisation mit Kästen für Stellen und Abteilungen und Linien für die Weisungswege.", "fa_begriff": "نمودار سازمانی (Organigramm)", "fa": "نقشه‌ی سازمان ساختاری با جعبه‌هایی برای پست‌ها و بخش‌ها و خط‌هایی برای مسیرهای دستور.", "ru_begriff": "органиграмма (Organigramm)", "ru": "Схема организационной структуры. Прямоугольники обозначают должности и отделы, линии обозначают пути указаний."}, {"id": 83, "tag": 7, "de_begriff": "Kongruenzprinzip", "de": "Aufgabe, Kompetenz und Verantwortung einer Stelle müssen zueinander passen.", "fa_begriff": "اصل تطابق (Kongruenzprinzip)", "fa": "وظیفه، اختیار و مسئولیت یک پست باید با هم هماهنگ باشند.", "ru_begriff": "принцип соответствия (Kongruenzprinzip)", "ru": "Задача, полномочия и ответственность одной должности должны соответствовать друг другу."}, {"id": 84, "tag": 7, "de_begriff": "Geschäftsprozess", "de": "Folge von Tätigkeiten über mehrere Abteilungen, die mit einem Auslöser beginnt und mit einem Ergebnis für den Kunden endet.", "fa_begriff": "فرایند کسب‌وکار (Geschäftsprozess)", "fa": "زنجیره‌ای از فعالیت‌ها در چند بخش که با یک عامل آغازگر شروع می‌شود و با نتیجه‌ای برای مشتری پایان می‌یابد.", "ru_begriff": "бизнес-процесс (Geschäftsprozess)", "ru": "Последовательность действий в нескольких отделах. Она начинается с повода и заканчивается результатом для клиента."}, {"id": 85, "tag": 8, "de_begriff": "Delegation", "de": "Eine vorgesetzte Person überträgt Aufgaben mit den passenden Befugnissen und der Verantwortung an Mitarbeitende.", "fa_begriff": "واگذاری وظایف (Delegation)", "fa": "یک مدیر وظایف را همراه با اختیارات لازم و مسئولیت آن‌ها به کارکنان واگذار می‌کند.", "ru_begriff": "делегирование (Delegation)", "ru": "Руководитель передаёт сотрудникам задачи вместе с нужными полномочиями и ответственностью."}, {"id": 86, "tag": 8, "de_begriff": "AKV-Prinzip", "de": "Aufgabe, Kompetenz und Verantwortung müssen zueinander passen. Wer eine Aufgabe hat, braucht auch die Befugnis dazu und trägt die Verantwortung.", "fa_begriff": "اصل AKV (AKV-Prinzip)", "fa": "وظیفه (Aufgabe)، اختیار (Kompetenz) و مسئولیت (Verantwortung) باید با هم هماهنگ باشند. کسی که وظیفه‌ای دارد، اختیار انجام آن را هم لازم دارد و مسئولیت آن را بر عهده دارد.", "ru_begriff": "принцип AKV (AKV-Prinzip)", "ru": "Задача (Aufgabe), полномочия (Kompetenz) и ответственность (Verantwortung) должны соответствовать друг другу. У кого есть задача, тому нужны и полномочия для неё, и он несёт ответственность."}, {"id": 87, "tag": 8, "de_begriff": "Kompetenz (Befugnis)", "de": "Das Recht, etwas zu tun, zum Beispiel entscheiden, anordnen, über Mittel verfügen oder das Unternehmen vertreten.", "fa_begriff": "اختیار (Kompetenz، Befugnis)", "fa": "حق انجام کاری، برای مثال تصمیم گرفتن، دستور دادن، استفاده از منابع یا نمایندگی شرکت.", "ru_begriff": "полномочия (Kompetenz, Befugnis)", "ru": "Право что-то делать, например принимать решения, давать распоряжения, распоряжаться средствами или представлять предприятие."}, {"id": 88, "tag": 8, "de_begriff": "Weisungssystem", "de": "Regelt, wer wem Anweisungen geben darf. Arten sind Einliniensystem, Mehrliniensystem, Stabliniensystem und Matrixorganisation.", "fa_begriff": "نظام دستوردهی (Weisungssystem)", "fa": "مشخص می‌کند چه کسی اجازه دارد به چه کسی دستور بدهد. انواع آن نظام تک‌خطی (Einliniensystem)، نظام چندخطی (Mehrliniensystem)، نظام تک‌خطی با پست مشاوره‌ای (Stabliniensystem) و سازمان ماتریسی (Matrixorganisation) هستند.", "ru_begriff": "система подчинения (Weisungssystem)", "ru": "Устанавливает, кто кому может давать указания. Различают линейную систему (Einliniensystem), многолинейную систему (Mehrliniensystem), линейно-штабную систему (Stabliniensystem) и матричную организацию (Matrixorganisation)."}, {"id": 89, "tag": 8, "de_begriff": "Matrixorganisation", "de": "Variante des Mehrliniensystems. Mitarbeitende haben einen Fachvorgesetzten und einen Produkt- oder Projektvorgesetzten.", "fa_begriff": "سازمان ماتریسی (Matrixorganisation)", "fa": "نوعی از نظام چندخطی. کارکنان یک مدیر تخصصی و یک مدیر محصول یا پروژه دارند.", "ru_begriff": "матричная организация (Matrixorganisation)", "ru": "Вариант многолинейной системы. У сотрудников есть руководитель по специальности и руководитель по продукту или проекту."}, {"id": 90, "tag": 8, "de_begriff": "Prokura", "de": "Umfassende Vollmacht nach §§ 48 bis 53 HGB. Sie wird ausdrücklich erteilt, ins Handelsregister eingetragen und mit ppa. gezeichnet.", "fa_begriff": "پروکورا، وکالت تجاری گسترده (Prokura)", "fa": "وکالتی گسترده طبق §§ 48 تا 53 HGB. این وکالت به‌صراحت داده می‌شود، در دفتر ثبت تجاری (Handelsregister) ثبت می‌شود و با ppa. امضا می‌شود.", "ru_begriff": "прокура (Prokura)", "ru": "Широкая доверенность по правилам с § 48 по § 53 HGB. Её выдают явно, вносят в торговый реестр (Handelsregister) и подписываются с пометкой ppa."}, {"id": 91, "tag": 8, "de_begriff": "Allgemeine Handlungsvollmacht", "de": "Vollmacht für alle gewöhnlichen Geschäfte eines derartigen Handelsgewerbes (§ 54 HGB), ohne Eintragung ins Handelsregister.", "fa_begriff": "وکالت عمومی تجاری (Allgemeine Handlungsvollmacht)", "fa": "وکالت برای همه‌ی معاملات معمولِ چنین کسب‌وکار تجاری‌ای (§ 54 HGB)، بدون ثبت در دفتر ثبت تجاری (Handelsregister).", "ru_begriff": "общая торговая доверенность (allgemeine Handlungsvollmacht)", "ru": "Доверенность на все обычные сделки такого торгового предприятия (§ 54 HGB), без внесения в торговый реестр (Handelsregister)."}, {"id": 92, "tag": 8, "de_begriff": "Artvollmacht", "de": "Handlungsvollmacht für eine bestimmte Art von Geschäften, zum Beispiel alle Einkäufe bis 50.000 €.", "fa_begriff": "وکالت برای نوع خاصی از معاملات (Artvollmacht)", "fa": "وکالت تجاری برای یک نوع مشخص از معاملات، برای مثال همه‌ی خریدها تا 50.000 €.", "ru_begriff": "доверенность на определённый вид сделок (Artvollmacht)", "ru": "Торговая доверенность на определённый вид сделок, например на все закупки до 50.000 €."}, {"id": 93, "tag": 8, "de_begriff": "Einzelvollmacht", "de": "Handlungsvollmacht für ein einzelnes Geschäft, zum Beispiel ein Einschreiben bei der Post abholen.", "fa_begriff": "وکالت برای یک معامله (Einzelvollmacht)", "fa": "وکالت تجاری برای یک کار واحد، برای مثال تحویل گرفتن یک نامه‌ی سفارشی از اداره‌ی پست.", "ru_begriff": "разовая доверенность (Einzelvollmacht)", "ru": "Торговая доверенность на одну отдельную сделку, например забрать заказное письмо на почте."}, {"id": 94, "tag": 8, "de_begriff": "Zeichnungszusatz", "de": "Kurzer Zusatz vor dem Namen bei der Unterschrift. Üblich sind ppa. für Prokura, i. V. für jede Handlungsvollmacht und i. A. für Aufträge ohne Vollmacht.", "fa_begriff": "افزوده‌ی امضا (Zeichnungszusatz)", "fa": "یک افزوده‌ی کوتاه پیش از نام هنگام امضا. معمول این‌ها هستند، ppa. برای پروکورا، i. V. برای هر نوع وکالت تجاری و i. A. برای مأموریت‌هایی بدون وکالت.", "ru_begriff": "пометка при подписи (Zeichnungszusatz)", "ru": "Короткая пометка перед именем при подписи. Обычно пишут ppa. для прокуры, i. V. для любой торговой доверенности и i. A. для поручений без доверенности."}, {"id": 95, "tag": 8, "de_begriff": "Handelsregister", "de": "Öffentliches Verzeichnis der Kaufleute. Dort stehen zum Beispiel die Firma, die Geschäftsführung und die Prokuristen.", "fa_begriff": "دفتر ثبت تجاری (Handelsregister)", "fa": "فهرست عمومی بازرگانان. در آن برای مثال نام تجاری شرکت (Firma)، مدیران و دارندگان پروکورا ثبت شده است.", "ru_begriff": "торговый реестр (Handelsregister)", "ru": "Открытый государственный список коммерсантов. Там указаны, например, фирменное название (Firma), руководство и прокуристы (Prokuristen)."}, {"id": 96, "tag": 9, "de_begriff": "Präsentation", "de": "Vortrag, bei dem Inhalte mit Medien wie Folien oder Flipchart für eine Zielgruppe anschaulich vorgestellt werden.", "fa_begriff": "ارائه (Präsentation)", "fa": "سخنرانی‌ای که در آن محتوا با کمک رسانه‌هایی مثل اسلاید یا فلیپ‌چارت به‌شکل روشن برای یک گروه مخاطب معرفی می‌شود.", "ru_begriff": "презентация (Präsentation)", "ru": "Выступление, на котором содержание наглядно представляют целевой группе с помощью средств, например слайдов или флипчарта."}, {"id": 97, "tag": 9, "de_begriff": "Zielgruppe", "de": "Die Personen, die zuhören. Ihr Vorwissen und ihre Erwartungen bestimmen Inhalt und Sprache.", "fa_begriff": "گروه مخاطب (Zielgruppe)", "fa": "افرادی که گوش می‌دهند. دانش قبلی و انتظارات آن‌ها محتوا و زبان ارائه را تعیین می‌کند.", "ru_begriff": "целевая группа (Zielgruppe)", "ru": "Люди, которые слушают. Их знания и ожидания определяют содержание и язык выступления."}, {"id": 98, "tag": 9, "de_begriff": "Zielgruppenanalyse", "de": "Vorher klären, wer zuhört, was diese Personen schon wissen, was sie erwarten und wie viele es sind.", "fa_begriff": "تحلیل گروه مخاطب (Zielgruppenanalyse)", "fa": "از قبل روشن کردن اینکه چه کسانی گوش می‌دهند، از قبل چه می‌دانند، چه انتظاری دارند و چند نفر هستند.", "ru_begriff": "анализ целевой группы (Zielgruppenanalyse)", "ru": "Заранее выяснить, кто слушает, что эти люди уже знают, чего они ожидают и сколько их."}, {"id": 99, "tag": 9, "de_begriff": "Ablaufplan", "de": "Plan mit der Reihenfolge der Inhalte, der Zeit für jeden Teil und den eingesetzten Medien.", "fa_begriff": "برنامه‌ی اجرا (Ablaufplan)", "fa": "برنامه‌ای با ترتیب محتواها، زمان هر بخش و رسانه‌هایی که استفاده می‌شوند.", "ru_begriff": "план проведения (Ablaufplan)", "ru": "План с последовательностью тем, временем для каждой части и используемыми средствами."}, {"id": 100, "tag": 9, "de_begriff": "Einleitung", "de": "Erster Teil. Begrüßung, Thema, warum das Thema wichtig ist, und die Gliederung.", "fa_begriff": "مقدمه (Einleitung)", "fa": "بخش اول. خوشامدگویی، موضوع، اینکه چرا موضوع مهم است و فهرست بخش‌ها.", "ru_begriff": "введение (Einleitung)", "ru": "Первая часть. Приветствие, тема, почему тема важна, и план выступления."}, {"id": 101, "tag": 9, "de_begriff": "Hauptteil", "de": "Mittlerer und längster Teil. Hier stehen die wesentlichen Inhalte in logischer Reihenfolge.", "fa_begriff": "بخش اصلی (Hauptteil)", "fa": "بخش میانی و طولانی‌ترین بخش. محتوای اصلی در اینجا با ترتیبی منطقی می‌آید.", "ru_begriff": "основная часть (Hauptteil)", "ru": "Средняя и самая длинная часть. Здесь главное содержание изложено в логическом порядке."}, {"id": 102, "tag": 9, "de_begriff": "Schluss", "de": "Letzter Teil. Kernpunkte zusammenfassen, Bezug zur Einleitung, Ausblick und Kernbotschaft.", "fa_begriff": "پایان ارائه (Schluss)", "fa": "بخش آخر. خلاصه کردن نکات اصلی، ارتباط با مقدمه، نگاه به آینده و پیام اصلی.", "ru_begriff": "заключение (Schluss)", "ru": "Последняя часть. Кратко повторить главные пункты, связать с введением, дать взгляд в будущее и главную мысль."}, {"id": 103, "tag": 9, "de_begriff": "Handout", "de": "Papier oder Datei mit den wichtigsten Inhalten, die das Publikum mitnehmen kann.", "fa_begriff": "جزوه‌ی همراه (Handout)", "fa": "کاغذ یا فایلی با مهم‌ترین محتواها که مخاطبان می‌توانند با خود ببرند.", "ru_begriff": "раздаточный материал (Handout)", "ru": "Бумага или файл с самым важным содержанием, которые слушатели могут взять с собой."}, {"id": 104, "tag": 9, "de_begriff": "Faustregel", "de": "Praktische Empfehlung aus der Erfahrung, kein Gesetz. Beispiel ist die 7x7-Regel für Folien.", "fa_begriff": "قاعده‌ی سرانگشتی (Faustregel)", "fa": "توصیه‌ای عملی بر اساس تجربه، نه یک قانون. یک مثال، قاعده‌ی 7x7 برای اسلایدهاست.", "ru_begriff": "практическое правило (Faustregel)", "ru": "Практическая рекомендация из опыта, а не закон. Например, правило 7x7 для слайдов."}, {"id": 105, "tag": 9, "de_begriff": "Lampenfieber", "de": "Nervosität vor einem Auftritt. Sie ist normal und lässt sich durch gute Vorbereitung verringern.", "fa_begriff": "اضطراب پیش از اجرا (Lampenfieber)", "fa": "عصبی بودن پیش از حضور در برابر جمع. این حالت طبیعی است و با آمادگی خوب کمتر می‌شود.", "ru_begriff": "волнение перед выступлением (Lampenfieber)", "ru": "Нервозность перед выступлением. Это нормально, и хорошая подготовка помогает её уменьшить."}, {"id": 106, "tag": 9, "de_begriff": "Kriterienbogen", "de": "Bewertungsbogen mit festen Punkten wie Inhalt, Struktur, Medien, Vortrag und Zeit.", "fa_begriff": "فرم معیارهای ارزیابی (Kriterienbogen)", "fa": "برگه‌ی ارزیابی با موارد ثابت مانند محتوا، ساختار، رسانه‌ها، ارائه‌ی شفاهی و زمان.", "ru_begriff": "оценочный лист (Kriterienbogen)", "ru": "Лист оценки с постоянными пунктами, например содержание, структура, средства, выступление и время."}, {"id": 107, "tag": 9, "de_begriff": "Ich-Botschaft", "de": "Feedback aus eigener Sicht, zum Beispiel „Ich konnte die Zahlen gut lesen“ statt „Du bist schlecht“.", "fa_begriff": "پیام از دیدگاه من (Ich-Botschaft)", "fa": "بازخورد از دیدگاه خود، برای مثال «من توانستم اعداد را به‌خوبی بخوانم» به جای «تو بد هستی».", "ru_begriff": "я-сообщение (Ich-Botschaft)", "ru": "Обратная связь от своего лица, например «Мне было легко читать цифры» вместо «Ты плохой»."}, {"id": 108, "tag": 10, "de_begriff": "Lernerfolgskontrolle (LEK)", "de": "Schriftliche Klausur am Ende des Lernfelds. Sie zeigt Ihnen und dem Träger, was Sie schon sicher können.", "fa_begriff": "آزمون سنجش یادگیری (Lernerfolgskontrolle، LEK)", "fa": "امتحان کتبی در پایان حوزه‌ی یادگیری (Lernfeld). این امتحان به شما و به مؤسسه‌ی آموزشی (Träger) نشان می‌دهد که چه چیزهایی را با اطمینان بلد هستید.", "ru_begriff": "контроль успеваемости (Lernerfolgskontrolle, LEK)", "ru": "Письменная контрольная работа в конце учебной области (Lernfeld). Она показывает вам и организатору курса (Träger), что вы уже уверенно умеете."}, {"id": 109, "tag": 10, "de_begriff": "Operator", "de": "Das Aufgabenwort in einer Klausuraufgabe, zum Beispiel nennen, erklären, begründen oder berechnen. Es sagt Ihnen, was genau Sie tun sollen.", "fa_begriff": "فعل دستوری سؤال (Operator)", "fa": "کلمه‌ی دستور در یک سؤال امتحانی، برای مثال نام بردن (nennen)، توضیح دادن (erklären)، دلیل آوردن (begründen) یا محاسبه کردن (berechnen). این کلمه به شما می‌گوید دقیقاً چه کاری باید انجام دهید.", "ru_begriff": "слово задания (Operator)", "ru": "Слово задания в контрольной работе, например назвать, объяснить, обосновать или вычислить. Оно говорит вам, что именно нужно сделать."}];
